use std::fs;
fn normalize(path:&str)->Vec<String>{fs::read_to_string(path).unwrap().lines().filter_map(|line|{let(a,b)=line.trim().split_once(':')?;u64::from_str_radix(a,16).ok()?;let mut s=b.split('#').next().unwrap().trim().to_owned();if let Some(i)=s.find("(%rip)"){let bytes=s.as_bytes();let mut start=i;while start>0&&(bytes[start-1].is_ascii_hexdigit()||bytes[start-1]==b'x'||bytes[start-1]==b'-'){start-=1;}s.replace_range(start..i,"RIP");}if let Some(i)=s.find(" <"){let start=s[..i].rfind(char::is_whitespace).unwrap()+1;s.replace_range(start..i,"TARGET");}Some(s)}).collect()}
fn main(){let root="/home/ubuntu/src/zopro-perf-work/bounded-gather-profile177";let a=normalize(&format!("{root}/g2-OFF.asm"));let b=normalize(&format!("{root}/g2-ON.asm"));fs::write(format!("{root}/g2-OFF.normalized"),a.join("\n")).unwrap();fs::write(format!("{root}/g2-ON.normalized"),b.join("\n")).unwrap();println!("OFF instructions {}, ON instructions {}, normalized mismatches {}",a.len(),b.len(),a.iter().zip(&b).filter(|(x,y)|x!=y).count());for(i,(x,y))in a.iter().zip(&b).enumerate().filter(|(_, (x,y))|x!=y).take(12){println!("{i}: OFF {x}\n     ON {y}");}}
